package com.pethop.shelter;
import com.pethop.security.SecurityUser; import com.pethop.shelter.dto.*; import jakarta.validation.Valid; import java.util.List; import java.util.UUID; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/shelters") public class AdminShelterController{private final AdminShelterService service;public AdminShelterController(AdminShelterService s){service=s;}@GetMapping("/pending")List<ShelterResponse> pending(){return service.pending();}@GetMapping("/{id}")ShelterResponse get(@PathVariable UUID id){return service.get(id);}@PatchMapping("/{id}/verification")ShelterResponse decide(@PathVariable UUID id,@AuthenticationPrincipal SecurityUser admin,@Valid @RequestBody VerificationDecisionRequest request){return service.decide(id,admin.user(),request);}}
